    if (!category || meanRow?.[0] !== "Mean") continue;
    for (const c of CN_EU_COLUMNS) {
      const v = meanRow[c.col];
      if (typeof v === "number") {
        customerStudy.push({
          category,
          model: c.model,
          region: c.region,
          mean: Math.round(v * 100) / 100,
          methodology: "direct_mean",
        });
      }
