              totalPct[m] += pct;
            }
          }
        }
        j++;
      }
      models.forEach((model, m) => {
        if (totalPct[m] > 0) {
          const vehicleCode = model.includes("G60") ? "G60" : model.includes("G70") ? "G70" : null;
          if (vehicleCode) {
            customerStudy.push({
              category,
              model,
              region: "US",
              mean: Math.round((weighted[m] / totalPct[m]) * 100) / 100,
              methodology: "distribution_derived",
            });
          }
        }
      });
      i = j;
    } else {
