147	          >
148	            {pending === "weights" ? "Saving…" : "Save weights & recompute"}
149	          </button>
150	        </div>
151	      )}
152	
153	      <div className="mt-4 flex flex-wrap items-center gap-2">
154	        <button
155	          onClick={() => act("approved")}
