182	
183	      <div className="mt-3 border-t border-white/10 pt-3">
184	        <div className="flex items-center gap-2">
185	          <input
186	            value={challengeArg}
187	            onChange={(e) => setChallengeArg(e.target.value)}
188	            placeholder="Challenge this score/rationale with your own argument…"
189	            className="flex-1 rounded-md border border-white/10 bg-black/30 px-2 py-1.5 text-xs text-neutral-200 placeholder:text-neutral-600"
190	          />
191	          <button
192	            onClick={sendChallenge}
193	            disabled={pending === "challenge"}
194	            className="rounded-md border border-violet-400/40 bg-violet-500/10 px-3 py-1.5 text-xs font-semibold text-violet-200 hover:bg-violet-500/20 disabled:opacity-50"
195	          >
196	            {pending === "challenge" ? "Re-assessing…" : "Challenge"}
197	          </button>
198	        </div>
199	        {challengeResult && (
200	          <p className={clsx("mt-2 text-xs", challengeResult.changed ? "text-emerald-300" : "text-neutral-400")}>
201	            {challengeResult.changed ? "Result changed: " : "Result unchanged: "}
202	            {challengeResult.explanation}
203	          </p>
204	        )}
205	      </div>
206	    </div>
207	  );
208	}
209	
210	function computeLiveScore(requirement: Requirement, weights: Record<string, number>) {
211	  const totalWeight = requirement.scoreFactors.reduce((s, f) => s + (weights[f.key] ?? f.weight), 0) || 1;
212	  const weighted = requirement.scoreFactors.reduce(
213	    (s, f) => s + f.rawValue * (weights[f.key] ?? f.weight),
214	    0,
215	  );
216	  return weighted / totalWeight;
217	}
