3	import { useEffect, useState, useCallback } from "react";
4	import Link from "next/link";
5	import { useParams } from "next/navigation";
6	import { api } from "@/lib/api-client";
7	import type {
8	  Workflow,
9	  Requirement,
10	  AuditLogEntry,
11	  AISummary,
12	  StakeholderReview,
13	  Stakeholder,
14	  Signal,
15	  SourceRecord,
16	} from "@/lib/types";
17	import { PipelineStrip } from "@/components/PipelineStrip";
18	import { RequirementCard } from "@/components/RequirementCard";
19	import { AuditLogPanel } from "@/components/AuditLogPanel";
20	import { ReviewerRow } from "@/components/ReviewerRow";
21	import { EvidenceBadge } from "@/components/EvidenceBadge";
22	
23	export default function WorkflowPage() {
24	  const params = useParams<{ componentId: string }>();
25	  const [workflow, setWorkflow] = useState<Workflow | null>(null);
26	  const [requirements, setRequirements] = useState<Requirement[]>([]);
27	  const [auditLog, setAuditLog] = useState<AuditLogEntry[]>([]);
28	  const [aiSummaries, setAISummaries] = useState<AISummary[]>([]);
29	  const [reviews, setReviews] = useState<StakeholderReview[]>([]);
30	  const [stakeholders, setStakeholders] = useState<Stakeholder[]>([]);
31	  const [signals, setSignals] = useState<Signal[]>([]);
32	  const [sources, setSources] = useState<SourceRecord[]>([]);
33	  const [selectedReqId, setSelectedReqId] = useState<string | null>(null);
34	  const [notFound, setNotFound] = useState(false);
35	
36	  const refresh = useCallback(async () => {
37	    const wf = await api.getWorkflowByComponent(params.componentId);
38	    if (!wf) {
39	      setNotFound(true);
40	      return;
41	    }
42	    setWorkflow(wf);
43	    const [reqs, log, summaries, revs, shs, sig] = await Promise.all([
44	      api.listRequirements(wf.id),
45	      api.getAuditLog(wf.id),
46	      api.getAISummaries(wf.id),
47	      api.listReviews(wf.id),
48	      api.listStakeholders(),
49	      api.getSignals(wf.id),
50	    ]);
51	    setRequirements(reqs);
52	    setAuditLog(log);
53	    setAISummaries(summaries);
54	    setReviews(revs);
55	    setStakeholders(shs);
56	    setSignals(sig.signals);
57	    setSources(sig.sources);
58	  }, [params.componentId]);
59	
60	  useEffect(() => {
61	    refresh();
62	  }, [refresh]);
63	
64	  function onRequirementChanged(updated: Requirement) {
65	    setRequirements((rs) => rs.map((r) => (r.id === updated.id ? updated : r)));
66	    refresh(); // pick up new audit log / summary entries
67	  }
68	
69	  if (notFound) {
70	    return (
71	      <main className="mx-auto max-w-2xl px-6 py-16 text-center">
72	        <p className="text-neutral-400">No workflow exists for this component yet.</p>
73	        <Link href="/" className="mt-4 inline-block text-sm text-sky-400 hover:text-sky-300">
74	          ← Back to landing page
75	        </Link>
76	      </main>
77	    );
78	  }
79	
80	  if (!workflow) {
81	    return <main className="px-6 py-16 text-center text-neutral-500">Loading…</main>;
82	  }
